// Cache-aside pattern with Redis (Node.js / ioredis)
import { Redis } from 'ioredis';

const redis = new Redis(process.env.REDIS_URL);
const TTL_SECONDS = 300; // 5-minute TTL — defense against missed invalidations

async function getUserById(userId) {
  const cacheKey = `user:${userId}`;

  // Step 1: Check cache first
  const cached = await redis.get(cacheKey);
  if (cached) {
    return JSON.parse(cached); // cache HIT — ~0.5ms
  }

  // Step 2: Cache MISS — query the read replica
  const user = await db.queryOne(
    'SELECT id, name, email, role FROM users WHERE id = $1',
    [userId]
  );

  // Step 3: Populate cache for subsequent requests
  if (user) {
    await redis.setex(cacheKey, TTL_SECONDS, JSON.stringify(user));
  }

  return user; // ~20ms on first request, ~0.5ms for the next 5 minutes
}

// Invalidate on write — delete, not update, to avoid race conditions
async function updateUserEmail(userId, newEmail) {
  await db.query(
    'UPDATE users SET email = $1, updated_at = NOW() WHERE id = $2',
    [newEmail, userId]
  );
  // Delete: next read fetches fresh data instead of risking a race
  // between the cache update and in-flight reads
  await redis.del(`user:${userId}`);
}

// Cache stampede protection — only one request fetches from DB on a cold miss
// Use a distributed lock or probabilistic early expiration in production
async function getUserByIdWithLock(userId) {
  const cacheKey = `user:${userId}`;
  const lockKey = `lock:user:${userId}`;

  const cached = await redis.get(cacheKey);
  if (cached) return JSON.parse(cached);

  // Try to acquire a short-lived lock
  const acquired = await redis.set(lockKey, '1', 'EX', 5, 'NX');
  if (!acquired) {
    // Another request is fetching — wait briefly and retry from cache
    await new Promise(r => setTimeout(r, 50));
    return getUserByIdWithLock(userId);
  }

  try {
    const user = await db.queryOne('SELECT * FROM users WHERE id = $1', [userId]);
    if (user) await redis.setex(cacheKey, TTL_SECONDS, JSON.stringify(user));
    return user;
  } finally {
    await redis.del(lockKey); // always release the lock
  }
}

// Async background jobs with BullMQ (Redis-backed queue)
import { Queue, Worker } from 'bullmq';

// Producer — runs in the HTTP handler
const emailQueue = new Queue('email-notifications', {
  connection: { host: process.env.REDIS_HOST }
});

// HTTP handler — fast, returns immediately
async function registerUser(req, res) {
  const user = await db.insert('users', {
    email: req.body.email,
    name: req.body.name,
  });

  // Enqueue async work — does NOT await the actual email send
  await emailQueue.add('welcome-email', {
    userId: user.id,
    email: user.email,
    name: user.name,
  }, {
    attempts: 3,                // retry up to 3 times on failure
    backoff: { type: 'exponential', delay: 2000 }, // 2s, 4s, 8s
    removeOnComplete: 100,      // keep last 100 completed jobs for debugging
    removeOnFail: 50,
  });

  res.status(201).json({ id: user.id }); // returns in ~5ms
}

// Consumer — runs in a separate worker process
const emailWorker = new Worker('email-notifications', async (job) => {
  if (job.name === 'welcome-email') {
    await emailService.send({
      to: job.data.email,
      subject: 'Welcome!',
      template: 'welcome',
      context: { name: job.data.name },
    });
    console.log(`Welcome email sent to ${job.data.email}`);
  }
}, {
  connection: { host: process.env.REDIS_HOST },
  concurrency: 5, // process 5 jobs simultaneously per worker process
});

// Scalability patterns — practical checklist with implementation notes

// 1. STATELESS APP SERVERS
//    Store sessions in Redis, not server memory
import session from 'express-session';
import RedisStore from 'connect-redis';
const sessionMiddleware = session({
  store: new RedisStore({ client: redis }),
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { secure: true, httpOnly: true, maxAge: 86400000 }
});

// 2. CONNECTION POOLING
//    Use a pool — never create one connection per request
import { Pool } from 'pg';
const pool = new Pool({
  host: process.env.DB_HOST,
  database: process.env.DB_NAME,
  max: 20,         // max 20 connections per app server instance
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});
// PgBouncer sits in front of PostgreSQL and further pools across all app instances

// 3. ROUTE READS TO REPLICAS
const primaryPool = new Pool({ host: process.env.DB_PRIMARY_HOST, max: 5 });
const replicaPool = new Pool({ host: process.env.DB_REPLICA_HOST, max: 20 });

async function findOrder(orderId) {
  // Non-critical read: can tolerate replica lag
  return replicaPool.query('SELECT * FROM orders WHERE id = $1', [orderId]);
}
async function createOrder(data) {
  // Write always goes to primary
  return primaryPool.query('INSERT INTO orders ...', data);
}

// 4. HTTP CACHE HEADERS FOR STATIC ASSETS
// In your static file middleware:
app.use('/assets', express.static('dist/assets', {
  setHeaders: (res, filePath) => {
    if (filePath.match(/\.[a-f0-9]{8}\./)) {
      // Content-hashed file — cache permanently
      res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
    } else {
      // Non-hashed file — always revalidate
      res.setHeader('Cache-Control', 'no-cache');
    }
  }
}));

// 5. RATE LIMITING with Redis sliding window
async function checkRateLimit(clientId, limit = 100, windowSec = 60) {
  const key = `rl:${clientId}`;
  const now = Date.now();
  const windowStart = now - windowSec * 1000;

  await redis.zremrangebyscore(key, '-inf', windowStart); // prune old entries
  const count = await redis.zcard(key);                   // count in window

  if (count >= limit) return { allowed: false, remaining: 0 };

  await redis.zadd(key, now, `${now}`);     // record this request
  await redis.expire(key, windowSec);       // TTL cleanup
  return { allowed: true, remaining: limit - count - 1 };
}
